import{_ as t,a0 as p,w as r,s as o,ao as d,I as l,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"CentOS 7 上的 FirewallD 简明指南 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS 7 上的 FirewallD 简明指南 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS 7 上的 FirewallD 简明指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS 7 上的 FirewallD 简明指南 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7","title":"CentOS 7 上的 FirewallD 简明指南","tag":"201703","desc":""},"relativePath":"201703/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md","filePath":"[post].md"}'),c={name:"201703/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md"};function h(g,s,m,f,u,b){const e=p("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="centos-7-上的-firewalld-简明指南" tabindex="-1">CentOS 7 上的 FirewallD 简明指南 <a class="header-anchor" href="#centos-7-上的-firewalld-简明指南" aria-label="Permalink to “CentOS 7 上的 FirewallD 简明指南”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2017/02/set-up-and-configure-a-firewall-with-firewalld-on-centos-7.jpg" alt=""></p><p>FirewallD 是 CentOS 7 服务器上默认可用的防火墙管理工具。基本上，它是 iptables 的封装，有图形配置工具 firewall-config 和命令行工具 <code>firewall-cmd</code>。使用 iptables 服务，每次改动都要求刷新旧规则，并且从 <code>/etc/sysconfig/iptables</code> 读取新规则，然而 firewalld 只应用改动了的不同部分。</p><h3 id="firewalld-的区域-zone" tabindex="-1">FirewallD 的区域（zone） <a class="header-anchor" href="#firewalld-的区域-zone" aria-label="Permalink to “FirewallD 的区域（zone）”">​</a></h3><p>FirewallD 使用服务（service） 和区域（zone）来代替 iptables 的规则（rule）和链（chain）。</p><p>默认情况下，有以下的区域（zone）可用：</p><ul><li><strong>drop</strong> – 丢弃所有传入的网络数据包并且无回应，只有传出网络连接可用。</li><li><strong>block</strong> — 拒绝所有传入网络数据包并回应一条主机禁止的 ICMP 消息，只有传出网络连接可用。</li><li><strong>public</strong> — 只接受被选择的传入网络连接，用于公共区域。</li><li><strong>external</strong> — 用于启用了地址伪装的外部网络，只接受选定的传入网络连接。</li><li><strong>dmz</strong> — DMZ 隔离区，外部受限地访问内部网络，只接受选定的传入网络连接。</li><li><strong>work</strong> — 对于处在你工作区域内的计算机，只接受被选择的传入网络连接。</li><li><strong>home</strong> — 对于处在你家庭区域内的计算机，只接受被选择的传入网络连接。</li><li><strong>internal</strong> — 对于处在你内部网络的计算机，只接受被选择的传入网络连接。</li><li><strong>trusted</strong> — 所有网络连接都接受。</li></ul><p>要列出所有可用的区域，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-zones</span></span>
<span class="line"><span>work drop internal external trusted home dmz public block</span></span></code></pre></div><p>列出默认的区域 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>public</span></span></code></pre></div><p>改变默认的区域 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><h3 id="firewalld-服务" tabindex="-1">FirewallD 服务 <a class="header-anchor" href="#firewalld-服务" aria-label="Permalink to “FirewallD 服务”">​</a></h3><p>FirewallD 服务使用 XML 配置文件，记录了 firewalld 服务信息。</p><p>列出所有可用的服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-services</span></span>
<span class="line"><span>amanda-client amanda-k5-client bacula bacula-client ceph ceph-mon dhcp dhcpv6 dhcpv6-client dns docker-registry dropbox-lansync freeipa-ldap freeipa-ldaps freeipa-replication ftp high-availability http https imap imaps ipp ipp-client ipsec iscsi-target kadmin kerberos kpasswd ldap ldaps libvirt libvirt-tls mdns mosh mountd ms-wbt mysql nfs ntp openvpn pmcd pmproxy pmwebapi pmwebapis pop3 pop3s postgresql privoxy proxy-dhcp ptp pulseaudio puppetmaster radius rpc-bind rsyncd samba samba-client sane smtp smtps snmp snmptrap squid ssh synergy syslog syslog-tls telnet tftp tftp-client tinc tor-socks transmission-client vdsm vnc-server wbem-https xmpp-bosh xmpp-client xmpp-local xmpp-server</span></span></code></pre></div><p>XML 配置文件存储在 <code>/usr/lib/firewalld/services/</code> 和 <code>/etc/firewalld/services/</code> 目录下。</p><h3 id="用-firewalld-配置你的防火墙" tabindex="-1">用 FirewallD 配置你的防火墙 <a class="header-anchor" href="#用-firewalld-配置你的防火墙" aria-label="Permalink to “用 FirewallD 配置你的防火墙”">​</a></h3><p>作为一个例子，假设你正在运行一个 web 服务器，SSH 服务端口为 7022 ，以及邮件服务，你可以利用 FirewallD 这样配置你的服务器:</p><p>首先设置默认区为 dmz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><p>为 dmz 区添加持久性的 HTTP 和 HTTPS 规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=dmz --add-service=http --permanent</span></span>
<span class="line"><span># firewall-cmd --zone=dmz --add-service=https --permanent</span></span></code></pre></div><p>开启端口 25 (SMTP) 和端口 465 (SMTPS) ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=smtp --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=smtps --permanent</span></span></code></pre></div><p>开启 IMAP、IMAPS、POP3 和 POP3S 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=imap --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=imaps --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3 --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3s --permanent</span></span></code></pre></div><p>因为将 SSH 端口改到了 7022，所以要移除 ssh 服务（端口 22），开启端口 7022：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --remove-service=ssh --permanent</span></span>
<span class="line"><span>firewall-cmd --add-port=7022/tcp --permanent</span></span></code></pre></div><p>要应用这些更改，我们需要重新加载防火墙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><p>最后可以列出这些规则：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd –list-all</span></span>
<span class="line"><span>dmz</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces:</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: http https imap imaps pop3 pop3s smtp smtps</span></span>
<span class="line"><span>ports: 7022/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>sourceports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><hr><p>PS. 如果你喜欢这篇文章，请在下面留下一个回复。谢谢。</p><hr>`,37)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/",-1)])]),_:1})]),s[16]||(s[16]=l("p",null,"译者简介：",-1)),l("p",null,[i(e,{href:"http://locez.com"},{default:n(()=>[...s[2]||(s[2]=[a("Locez",-1)])]),_:1}),s[3]||(s[3]=a(" 是一个喜欢技术，喜欢折腾的 Linuxer，靠着对 Linux 的兴趣自学了很多 Linux 相关的知识，并且志在于为 Linux 在中国普及出一份力。",-1))]),l("p",null,[s[7]||(s[7]=a("作者：",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:n(()=>[...s[4]||(s[4]=[a("rosehosting.com",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(e,{href:"https://github.com/locez"},{default:n(()=>[...s[5]||(s[5]=[a("Locez",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(e,{href:"https://github.com/jasminepeng"},{default:n(()=>[...s[6]||(s[6]=[a("jasminepeng",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const v=t(c,[["render",h]]);export{C as __pageData,v as default};
